// ProductDetailPage.js - FINAL FIX: Indonesia + Full Ingredients Display

import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';

const ProductDetailPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  
  // State management
  const [product, setProduct] = useState(null);
  const [ingredients, setIngredients] = useState([]);
  const [safetyAnalysis, setSafetyAnalysis] = useState(null);
  const [similarProducts, setSimilarProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState('overview');
  const [imageError, setImageError] = useState(false);

  // TRANSLATION OBJECT - Bahasa Indonesia
  const translations = {
    'Loading product details...': 'Memuat detail produk...',
    'Product Not Found': 'Produk Tidak Ditemukan',
    'Back to Products': 'Kembali ke Produk',
    'Retry': 'Coba Lagi',
    'Home': 'Beranda',
    'Products': 'Produk',
    'Add to Favorites': 'Tambahkan ke Favorit',
    'Visit Store': 'Kunjungi Toko',
    'Unknown Brand': 'Merek Tidak Diketahui',
    "What's Inside (and What Isn't)": 'Apa yang Ada (dan Tidak Ada) di Dalamnya',
    'Safety Information': 'Informasi Keamanan',
    'Overview': 'Ringkasan',
    'Ingredients': 'Bahan-Bahan',
    'How to Use': 'Cara Penggunaan',
    'Product Description': 'Deskripsi Produk',
    'No description available for this product.': 'Tidak ada deskripsi untuk produk ini.',
    'Suitable For': 'Cocok Untuk',
    'Skin': 'Kulit',
    'Addresses Concerns': 'Mengatasi Masalah',
    'Key Ingredients': 'Bahan Aktif Utama',
    'Full Ingredient List': 'Daftar Lengkap Bahan',
    'Similar Products': 'Produk Serupa',
    'Usage instructions not available for this product.': 'Instruksi penggunaan tidak tersedia untuk produk ini.'
  };

  const t = (text) => translations[text] || text;

  // Load product data on mount
  useEffect(() => {
    if (id) {
      loadProductDetail();
    }
  }, [id]);

  // FIXED: Load complete product information
  const loadProductDetail = async () => {
    setLoading(true);
    setError('');

    try {
      console.log(`🔍 Loading product detail for ID: ${id}`);
      
      // 1. Load basic product info
      const productResponse = await fetch(`http://localhost:5000/api/products/${id}`);
      
      if (!productResponse.ok) {
        throw new Error(`Product not found (${productResponse.status})`);
      }
      const productData = await productResponse.json();

      console.log('🔍 Raw API Response structure:', Object.keys(productData));

      // Handle different response structures
      let product = null;
      if (productData.success && productData.product) {
        product = productData.product;
      } else if (productData.success && productData.data) {
        product = productData.data;
      } else if (productData.product) {
        product = productData.product;
      } else {
        throw new Error('Product data not found in response');
      }

      console.log('✅ Processed Product data:', {
        id: product.id,
        name: product.name,
        hasIngredientList: !!product.ingredient_list,
        hasKeyIngredients: !!product.key_ingredients,
        ingredientListPreview: product.ingredient_list?.substring(0, 100) + '...'
      });
      
      setProduct(product);

      // 2. ALWAYS parse FULL ingredient list - INI YANG PENTING
      await parseFullIngredientList(product);

      // 3. Load similar products
      await loadSimilarProducts(product);

    } catch (error) {
      console.error('❌ Product detail error:', error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  // FIXED: Parse FULL ingredient list properly
  const parseFullIngredientList = async (product) => {
    try {
      console.log('🧪 PARSING FULL INGREDIENT LIST...');
      console.log('🔍 Product data received:', {
        hasIngredientList: !!product.ingredient_list,
        hasKeyIngredients: !!product.key_ingredients,
        hasIngredientsArray: !!(product.ingredients && product.ingredients.length > 0),
        ingredientListLength: product.ingredient_list?.length || 0,
        keyIngredientsLength: product.key_ingredients?.length || 0
      });
      
      let allIngredients = [];
      let keyIngredientsArray = [];
      
      // 1. Parse key ingredients first
      if (product.key_ingredients) {
        keyIngredientsArray = product.key_ingredients
          .split(/[,|;]/)
          .map(ing => ing.trim())
          .filter(ing => ing.length > 2)
          .map(ing => ing.toUpperCase()); // Normalize to uppercase
        console.log(`🔑 Found ${keyIngredientsArray.length} key ingredients:`, keyIngredientsArray);
      }
      
      // 2. Parse ALL ingredients from ingredient_list - INI YANG PALING PENTING
      if (product.ingredient_list) {
        console.log('📋 Raw ingredient_list:', product.ingredient_list);
        
        // Remove common prefixes like "KOMPOSISI:", "INGREDIENTS:", etc
        let cleanedList = product.ingredient_list
          .replace(/^(KOMPOSISI\s*:?\s*|INGREDIENTS\s*:?\s*|BAHAN\s*:?\s*|INCI\s*:?\s*)/i, '')
          .trim();
        
        console.log('📋 Cleaned ingredient_list:', cleanedList);
        
        // Split by common separators and clean
        allIngredients = cleanedList
          .split(/[,|;]/)
          .map(ing => {
            // Clean each ingredient
            return ing
              .trim()
              .replace(/^\d+\.\s*/, '') // Remove numbering like "1. "
              .replace(/^-\s*/, '')     // Remove dashes "- "
              .replace(/\s+/g, ' ')     // Normalize spaces
              .toUpperCase();           // Normalize to uppercase
          })
          .filter(ing => {
            // Filter out empty, too short, or invalid ingredients
            return ing.length > 2 && 
                   !ing.match(/^(DLL|ETC|AND|OR|WATER\s*\()$/i) &&
                   !ing.match(/^\d+$/); // Remove pure numbers
          });
          
        console.log(`📋 Parsed ${allIngredients.length} total ingredients from ingredient_list`);
        console.log('📋 First 10 ingredients:', allIngredients.slice(0, 10));
      }
      
      // 3. If no ingredient_list, try to get from backend ingredients array
      if (allIngredients.length === 0 && product.ingredients && product.ingredients.length > 0) {
        allIngredients = product.ingredients.map(ing => ing.name.toUpperCase());
        console.log(`🔄 Using backend ingredients array: ${allIngredients.length} ingredients`);
      }
      
      // 4. If still no ingredients, create minimal list from key ingredients
      if (allIngredients.length === 0 && keyIngredientsArray.length > 0) {
        allIngredients = [...keyIngredientsArray];
        console.log(`⚠️ Fallback: Using only key ingredients as full list`);
      }
      
      // 5. Create ingredient analysis array - SEMUA INGREDIENTS DITAMPILKAN
      const ingredientAnalysis = [];
      
      console.log(`🎯 Processing ${allIngredients.length} ingredients for display...`);
      
      // Process ALL ingredients (not just key ones)
      for (const ingredient of allIngredients) {
        const isKey = keyIngredientsArray.some(key => 
          key.toUpperCase() === ingredient.toUpperCase()
        );
        
        // Try to get ontology data for key ingredients
        let ontologyData = null;
        if (isKey) {
          try {
            ontologyData = await queryIngredientOntology(ingredient);
          } catch (error) {
            console.warn(`⚠️ Ontology query failed for key ingredient: ${ingredient}`, error);
          }
        }
        
        ingredientAnalysis.push({
          name: ingredient,
          isKey: isKey,
          ontologyData: ontologyData,
          ontologyPowered: !!ontologyData
        });
      }
      
      setIngredients(ingredientAnalysis);
      console.log(`✅ FULL INGREDIENT ANALYSIS COMPLETE:`);
      console.log(`   - Total ingredients displayed: ${ingredientAnalysis.length}`);
      console.log(`   - Key ingredients: ${ingredientAnalysis.filter(ing => ing.isKey).length}`);
      console.log(`   - Ontology analyzed: ${ingredientAnalysis.filter(ing => ing.ontologyPowered).length}`);
      
      // Show sample of what will be displayed
      console.log('📋 Sample ingredients to be displayed:', 
        ingredientAnalysis.slice(0, 10).map(ing => `${ing.name}${ing.isKey ? ' (KEY)' : ''}`));
      
      // Perform safety analysis
      await performSafetyAnalysis(ingredientAnalysis);
      
    } catch (error) {
      console.error('❌ Full ingredient parsing error:', error);
      setIngredients([]);
    }
  };

  // FIXED: Query ontology for specific ingredient
  const queryIngredientOntology = async (ingredient) => {
    try {
      const response = await fetch(`http://localhost:5000/api/ingredients?search=${encodeURIComponent(ingredient)}&limit=1`);
      const data = await response.json();
      
      if (data.success && data.data && data.data.length > 0) {
        return data.data[0];
      }
      
      return null;
    } catch (error) {
      console.warn(`⚠️ Ontology query failed for: ${ingredient}`);
      return null;
    }
  };

  // FIXED: Simplified safety analysis
  const performSafetyAnalysis = async (ingredientAnalysis) => {
    try {
      const safetyFlags = [];
      const ontologyInsights = [];
      let overallSafety = 'Aman';
      let ontologyConfidence = 0;
      
      // Analyze ontology-powered ingredients
      ingredientAnalysis.forEach(ingredient => {
        if (ingredient.ontologyData) {
          ontologyConfidence += 1;
          
          const data = ingredient.ontologyData;
          
          // Add insights
          if (data.benefit) {
            ontologyInsights.push({
              ingredient: ingredient.name,
              insight: data.benefit,
              category: data.category || 'Umum'
            });
          }
          
          // Safety warnings
          if (data.safety && data.safety.toLowerCase().includes('caution')) {
            safetyFlags.push({
              type: 'warning',
              ingredient: ingredient.name,
              message: `${ingredient.name}: ${data.safety}`
            });
            overallSafety = 'Perlu Hati-hati';
          }
        }
      });
      
      // Calculate confidence percentage
      const confidencePercentage = ingredientAnalysis.length > 0 
        ? Math.round((ontologyConfidence / ingredientAnalysis.length) * 100)
        : 0;
      
      // Product-level safety properties
      const safetyProps = [];
      if (product?.alcohol_free) safetyProps.push('Bebas Alkohol');
      if (product?.fragrance_free) safetyProps.push('Bebas Pewangi');
      if (product?.paraben_free) safetyProps.push('Bebas Paraben');
      if (product?.sulfate_free) safetyProps.push('Bebas Sulfat');
      if (product?.silicone_free) safetyProps.push('Bebas Silikon');
      
      setSafetyAnalysis({
        overallSafety,
        flags: safetyFlags,
        properties: safetyProps,
        ontologyInsights,
        ontologyConfidence: confidencePercentage,
        analysis: `Analisis ontologi lanjutan dari ${ingredientAnalysis.length} bahan (${confidencePercentage}% cakupan ontologi)`
      });
      
      console.log(`✅ SAFETY ANALYSIS COMPLETE: ${safetyFlags.length} peringatan, ${ontologyInsights.length} wawasan`);
      
    } catch (error) {
      console.error('❌ Safety analysis error:', error);
    }
  };

  // Load similar products
  const loadSimilarProducts = async (currentProduct) => {
    try {
      console.log('🔍 Finding similar products...');
      
      const params = new URLSearchParams({
        category: currentProduct.main_category || '',
        limit: '4'
      });

      const response = await fetch(`http://localhost:5000/api/products?${params}`);
      const data = await response.json();

      if (data.success) {
        const similar = data.data
          .filter(p => p.id !== currentProduct.id)
          .slice(0, 4);
        
        setSimilarProducts(similar);
        console.log(`✅ Found ${similar.length} similar products`);
      }

    } catch (error) {
      console.error('❌ Similar products error:', error);
    }
  };

  // Handle image error
  const handleImageError = () => {
    setImageError(true);
  };

  // Get image URL with fallback
  const getImageUrl = () => {
    if (!product) return '/images/placeholder-product.jpg';
    
    if (product.image_urls && !imageError) {
      return product.image_urls;
    }
    return '/images/placeholder-product.jpg';
  };

  // Loading state
  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600">{t('Loading product details...')}</p>
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">⚠️</div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">{t('Product Not Found')}</h1>
          <p className="text-gray-600 mb-6">{error}</p>
          <div className="space-x-4">
            <button
              onClick={() => navigate('/products')}
              className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition-colors"
            >
              {t('Back to Products')}
            </button>
            <button
              onClick={() => window.location.reload()}
              className="bg-gray-600 text-white px-6 py-3 rounded-lg hover:bg-gray-700 transition-colors"
            >
              {t('Retry')}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!product) return null;

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* Breadcrumb - INDONESIA */}
        <nav className="flex items-center space-x-2 text-sm text-gray-600 mb-6">
          <Link to="/" className="hover:text-blue-600">{t('Home')}</Link>
          <span>›</span>
          <Link to="/products" className="hover:text-blue-600">{t('Products')}</Link>
          <span>›</span>
          <span className="text-gray-900">{product.name}</span>
        </nav>

        {/* Main Product Section */}
        <div className="bg-white rounded-lg shadow-lg overflow-hidden mb-8">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 p-8">
            {/* Product Image */}
            <div className="space-y-4">
              <div className="aspect-square bg-gray-100 rounded-lg overflow-hidden">
                {imageError ? (
                  <div className="w-full h-full flex items-center justify-center bg-gray-100">
                    <div className="text-center text-gray-400">
                      <span className="text-6xl mb-4 block">🧴</span>
                      <span>Gambar Produk</span>
                    </div>
                  </div>
                ) : (
                  <img
                    src={getImageUrl()}
                    alt={product.name}
                    className="w-full h-full object-cover"
                    onError={handleImageError}
                  />
                )}
              </div>
            </div>

            {/* Product Info */}
            <div className="space-y-6">
              {/* Brand & Category */}
              <div className="text-sm text-gray-600">
                <span className="font-medium">{product.brand_name || product.brand?.name || t('Unknown Brand')}</span>
                {product.product_type && (
                  <>
                    <span className="mx-2">•</span>
                    <span>{product.product_type}</span>
                  </>
                )}
              </div>

              {/* Product Name */}
              <h1 className="text-3xl font-bold text-gray-900">{product.name}</h1>

              {/* Categories */}
              <div className="flex flex-wrap gap-2">
                {product.main_category && (
                  <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm">
                    {product.main_category}
                  </span>
                )}
                {product.subcategory && (
                  <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-sm">
                    {product.subcategory}
                  </span>
                )}
              </div>

              {/* Product Properties - INDONESIA */}
              {safetyAnalysis && safetyAnalysis.properties.length > 0 && (
                <div className="border-l-4 border-green-500 bg-green-50 p-4 rounded">
                  <h3 className="font-semibold text-green-800 mb-2">{t("What's Inside (and What Isn't)")}</h3>
                  <div className="flex flex-wrap gap-2">
                    {safetyAnalysis.properties.map((prop, index) => (
                      <span key={index} className="px-2 py-1 bg-green-200 text-green-800 rounded text-sm">
                        ✓ {prop}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {/* Safety Analysis - INDONESIA */}
              {safetyAnalysis && safetyAnalysis.flags.length > 0 && (
                <div className="border-l-4 border-yellow-500 bg-yellow-50 p-4 rounded">
                  <h3 className="font-semibold text-yellow-800 mb-2">{t('Safety Information')}</h3>
                  <div className="space-y-2">
                    {safetyAnalysis.flags.map((flag, index) => (
                      <div key={index} className="text-sm text-yellow-700">
                        <strong>{flag.type === 'warning' ? '⚠️' : 'ℹ️'}</strong> {flag.message}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Action Buttons - INDONESIA */}
              <div className="flex space-x-4">
                <button className="flex-1 bg-blue-600 text-white py-3 px-6 rounded-lg hover:bg-blue-700 transition-colors">
                  {t('Add to Favorites')} ♡
                </button>
                {product.product_url && (
                  <a
                    href={product.product_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex-1 bg-gray-600 text-white py-3 px-6 rounded-lg hover:bg-gray-700 transition-colors text-center"
                  >
                    {t('Visit Store')} 🛒
                  </a>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Detailed Information Tabs - INDONESIA */}
        <div className="bg-white rounded-lg shadow-lg overflow-hidden mb-8">
          {/* Tab Headers */}
          <div className="border-b border-gray-200">
            <div className="flex">
              {[
                { key: 'overview', label: t('Overview'), icon: '📋' },
                { key: 'ingredients', label: t('Ingredients'), icon: '🧪' },
                { key: 'usage', label: t('How to Use'), icon: '📖' }
              ].map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={`flex-1 px-6 py-4 text-center font-medium transition-colors ${
                    activeTab === tab.key
                      ? 'text-blue-600 border-b-2 border-blue-600 bg-blue-50'
                      : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
                  }`}
                >
                  <span className="mr-2">{tab.icon}</span>
                  {tab.label}
                </button>
              ))}
            </div>
          </div>

          {/* Tab Content */}
          <div className="p-8">
            {activeTab === 'overview' && (
              <div className="space-y-6">
                <div>
                  <h3 className="text-lg font-semibold mb-3">{t('Product Description')}</h3>
                  <p className="text-gray-700 leading-relaxed">
                    {product.description || t('No description available for this product.')}
                  </p>
                </div>

                {product.suitable_for_skin_types && (
                  <div>
                    <h3 className="text-lg font-semibold mb-3">{t('Suitable For')}</h3>
                    <div className="flex flex-wrap gap-2">
                      {product.suitable_for_skin_types.split(',').map((skinType, index) => (
                        <span key={index} className="px-3 py-1 bg-purple-100 text-purple-700 rounded-full text-sm">
                          {t('Skin')} {skinType.trim()}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {product.addresses_concerns && (
                  <div>
                    <h3 className="text-lg font-semibold mb-3">{t('Addresses Concerns')}</h3>
                    <div className="flex flex-wrap gap-2">
                      {product.addresses_concerns.split(',').map((concern, index) => (
                        <span key={index} className="px-3 py-1 bg-red-100 text-red-700 rounded-full text-sm">
                          {concern.trim()}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* FIXED: Single Ingredients Tab - NO MORE DUPLICATES */}
            {activeTab === 'ingredients' && (
              <div className="space-y-6">
                {/* ONTOLOGY CONFIDENCE INDICATOR - INDONESIA */}
                {safetyAnalysis?.ontologyConfidence !== undefined && (
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-semibold text-blue-800">🧠 Cakupan Analisis Ontologi</h4>
                        <p className="text-sm text-blue-600">
                          {safetyAnalysis.ontologyConfidence}% bahan dianalisis dengan pengetahuan semantik
                        </p>
                      </div>
                      <div className="text-2xl font-bold text-blue-600">
                        {safetyAnalysis.ontologyConfidence}%
                      </div>
                    </div>
                  </div>
                )}

                {/* KEY INGREDIENTS SECTION - INDONESIA */}
                <div>
                  <h3 className="text-lg font-semibold mb-4">
                    🔬 {t('Key Ingredients')} 
                    <span className="text-sm font-normal text-gray-600 ml-2">
                      (Analisis Semantik SPARQL)
                    </span>
                  </h3>
                  
                  <div className="space-y-4">
                    {ingredients.filter(ing => ing.isKey).map((ingredient, index) => (
                      <div key={index} className={`border rounded-lg p-4 ${
                        ingredient.ontologyPowered ? 'border-green-200 bg-green-50' : 'border-gray-200'
                      }`}>
                        <div className="flex items-start justify-between">
                          <h4 className="font-semibold text-gray-900 mb-2">{ingredient.name}</h4>
                          
                          {/* ONTOLOGY POWERED BADGE - INDONESIA */}
                          {ingredient.ontologyPowered && (
                            <span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-medium rounded-full">
                              🧠 Terverifikasi Ontologi
                            </span>
                          )}
                        </div>
                        
                        {ingredient.ontologyData ? (
                          <div className="space-y-2 text-sm">
                            {ingredient.ontologyData.what_it_does && (
                              <div className="flex items-start">
                                <span className="font-medium text-blue-600 mr-2">🔧 Fungsi:</span>
                                <span className="text-gray-700">{ingredient.ontologyData.what_it_does}</span>
                              </div>
                            )}
                            {ingredient.ontologyData.benefit && (
                              <div className="flex items-start">
                                <span className="font-medium text-green-600 mr-2">✨ Manfaat:</span>
                                <span className="text-gray-700">{ingredient.ontologyData.benefit}</span>
                              </div>
                            )}
                            {ingredient.ontologyData.explanation && (
                              <div className="flex items-start">
                                <span className="font-medium text-purple-600 mr-2">📚 Detail:</span>
                                <span className="text-gray-700">{ingredient.ontologyData.explanation}</span>
                              </div>
                            )}
                          </div>
                        ) : (
                          <div className="text-sm text-gray-600 bg-gray-50 p-3 rounded">
                            <div className="flex items-center">
                              <span className="text-yellow-500 mr-2">⏳</span>
                              <span>Bahan aktif - analisis ontologi tertunda atau tidak tersedia</span>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </div>

                {/* ONTOLOGY INSIGHTS SECTION - INDONESIA */}
                {safetyAnalysis?.ontologyInsights && safetyAnalysis.ontologyInsights.length > 0 && (
                  <div>
                    <h3 className="text-lg font-semibold mb-4">
                      🧠 Wawasan Ontologi
                      <span className="text-sm font-normal text-gray-600 ml-2">
                        (Analisis Graf Pengetahuan)
                      </span>
                    </h3>
                    
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                      <div className="space-y-3">
                        {safetyAnalysis.ontologyInsights.map((insight, index) => (
                          <div key={index} className="flex items-start">
                            <span className="text-blue-600 mr-2">💡</span>
                            <div>
                              <span className="font-medium text-blue-800">{insight.ingredient}:</span>
                              <span className="text-blue-700 ml-1">{insight.insight}</span>
                              {insight.category && (
                                <span className="text-xs text-blue-500 ml-2">({insight.category})</span>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {/* FULL INGREDIENT LIST - FIXED & INDONESIA */}
                <div>
                  <h3 className="text-lg font-semibold mb-4">📋 {t('Full Ingredient List')}</h3>
                  <div className="bg-gray-50 rounded-lg p-4">
                    <div className="flex flex-wrap gap-1">
                      {ingredients.map((ingredient, index) => (
                        <span
                          key={index}
                          className={`inline-block px-2 py-1 rounded text-xs transition-colors ${
                            ingredient.isKey
                              ? 'bg-blue-100 text-blue-700 font-medium border border-blue-200'
                              : ingredient.ontologyPowered
                              ? 'bg-green-100 text-green-700 border border-green-200'
                              : 'bg-gray-200 text-gray-700'
                          }`}
                          title={ingredient.ontologyPowered ? 'Dianalisis dengan ontologi' : 'Bahan standar'}
                        >
                          {ingredient.ontologyPowered && '🧠 '}
                          {ingredient.name}
                        </span>
                      ))}
                    </div>
                    
                    {/* INGREDIENT STATISTICS - INDONESIA */}
                    <div className="mt-4 pt-4 border-t border-gray-200">
                      <div className="grid grid-cols-3 gap-4 text-sm">
                        <div className="text-center">
                          <div className="font-semibold text-gray-900">{ingredients.length}</div>
                          <div className="text-gray-600">Total Bahan</div>
                        </div>
                        <div className="text-center">
                          <div className="font-semibold text-blue-600">{ingredients.filter(ing => ing.isKey).length}</div>
                          <div className="text-gray-600">Bahan Aktif</div>
                        </div>
                        <div className="text-center">
                          <div className="font-semibold text-green-600">{ingredients.filter(ing => ing.ontologyPowered).length}</div>
                          <div className="text-gray-600">Dianalisis Ontologi</div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'usage' && (
              <div>
                <h3 className="text-lg font-semibold mb-4">{t('How to Use')}</h3>
                <div className="prose prose-gray max-w-none">
                  <p className="text-gray-700 leading-relaxed whitespace-pre-line">
                    {product.how_to_use || t('Usage instructions not available for this product.')}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Similar Products - INDONESIA */}
        {similarProducts.length > 0 && (
          <div className="bg-white rounded-lg shadow-lg p-8">
            <h2 className="text-2xl font-bold mb-6">{t('Similar Products')}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {similarProducts.map((similar) => (
                <Link
                  key={similar.id}
                  to={`/products/${similar.id}`}
                  className="group border border-gray-200 rounded-lg overflow-hidden hover:shadow-md transition-shadow"
                >
                  <div className="aspect-square bg-gray-100">
                    <img
                      src={similar.image_urls || '/images/placeholder-product.jpg'}
                      alt={similar.name}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                      onError={(e) => {
                        e.target.src = '/images/placeholder-product.jpg';
                      }}
                    />
                  </div>
                  <div className="p-4">
                    <p className="text-sm text-gray-600 mb-1">{similar.brand_name}</p>
                    <h3 className="font-medium text-gray-900 line-clamp-2 group-hover:text-blue-600 transition-colors">
                      {similar.name}
                    </h3>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductDetailPage;
